window.EW=window.EW||{pages:{}};window.EW.pages["wiki-bestiaire--rang-aa"]={"html":"<div class=\"tbl-wrap\"><table class=\"doc-table\"><thead><tr><th scope=\"col\">Rang<\/th><th scope=\"col\">Description<\/th><\/tr><\/thead><tbody><tr><td>Grand Piscet des chênes<\/td><td>Rapace au plumage de feuilles, discret, jadis braconné au point de disparaître d'Europe du Nord pendant plus d'un siècle.<\/td><\/tr><tr><td>Naberus<\/td><td>Grand herbivore d'Afrique de l'Est vivant en troupeaux matriarcaux, territorial mais peu agressif.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--mange-lumiere-luciphage\">Mange-Lumière (Luciphage)<\/a><\/td><td>Petite créature semblable à une chauve-souris, dont les ailes semblent absorber la lumière.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--gratte-mur-arcanophage\">Gratte-Mur (Arcanophage)<\/a><\/td><td>Petite créature à pattes de lézard qui vit de la magie résiduelle des bâtiments anciens.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--folumix\">Folumix<\/a><\/td><td>Oiseau à l'allure d'aigle des arbres les plus anciens, défensif, reconnaissable à sa longue queue en forme de feuille.<\/td><\/tr><tr><td>Brumeret<\/td><td>Oiseau à l'allure de corbeau, au plumage noir à reflets violets.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--scalvignus\">Scalvignus<\/a><\/td><td>Cerf écailleux, discret et prudent, dont les larges bois tombent à la fin de l'hiver.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--praedacornis\">Praedacornis<\/a><\/td><td>Créature sociale et joueuse, semblable à une loutre cornue, qui mord avec force si on la menace.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--multaille\">Multaille<\/a><\/td><td>Oiseau tout rond dont le corps entier se réorganise en quelques secondes sous l'effet du stress.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aa--araignee-dether\">Araignée d'Ether<\/a><\/td><td>Araignée d'Ether de taille moyenne ayant prise Brûlebrume comme territoire.<\/td><\/tr><\/tbody><\/table><\/div>","toc":[]};
